new = []
def add(slug,title,topic,summary,facts,known,unknowns,who,what,when,where,why,how,money,relations,counter,options,actions,sources,qified,aliases,questions,issue_ids,ee):
    n=len(new)+4
    r=dict(id=f'QP-QIFY-2026-{n:03}',slug=slug,title=title,topic=topic,stage='SOURCE-ATTRIBUTED EXPLANATORY REPORT · INDEPENDENT REVIEW OPEN',date=DATE,review='Stated source sections checked; independent review and full outcome reconciliation remain open.',summary=summary,keyFacts=[dict(label=a,value=b,stage=c,source=d) for a,b,c,d in facts],whatKnown=known,unknowns=unknowns,who=who,what=what,when=when,where=where,why=why,how=how,money=[dict(stage=a,detail=b,status=c) for a,b,c in money],relations=relations,counter=counter,options=options,actions=actions,sources=sources,child=qified['childImpact']['present'],ee=ee,t2y='Truth-to-Yield: use the supported record to identify a practical next step; no numerical score or verified community outcome is inferred.',rx='Keep original source dates and alternative explanations. Reopen this analysis when the listed records or corrections become available.',qification=qified,aliases=aliases,questions=questions,issueIds=issue_ids)
    new.append(r)

add('permits-jurisdiction','Building permits: location determines the responsible authority','Government & law',
 'The current County and Southern Colorado Building Department pages distinguish City of Pueblo/Town of Boone projects from unincorporated Pueblo County projects. A Pueblo mailing address alone does not identify the permitting authority.',
 [('City of Pueblo and Boone','Southern Colorado Building Department','Published service jurisdiction','socobd'),('Unincorporated county','Pueblo County Building Division','Published service jurisdiction','county-permits'),('County transition','January 1, 2026','Published operational transition date','county-permits')],
 ['The County portal routes projects by jurisdiction and provides access to pre-2026 historical permit records.','SoCoBD publishes a separate transition notice and 2026 fee/code changes.'],
 ['The correct authority for an individual parcel still requires the official jurisdiction map and agency confirmation.','Project-specific fees, code edition, utility approvals and transfer status are not determined by this report.'],
 'County Building Division for unincorporated areas; SoCoBD for the City and Boone, subject to parcel confirmation.','Jurisdiction, historical permits and continuity across the 2026 transition.','Transition effective January 1, 2026; web guidance checked November 9.','City of Pueblo, Boone and unincorporated Pueblo County, including Pueblo West.','A misrouted application can add avoidable delay and leave missing inspection or permit history.','Confirm parcel jurisdiction; retrieve the historical permit; ask the receiving authority which approval, fees and inspections remain required.',
 [('Estimate','Project-specific permit and plan-review fees','No fee estimate calculated here.'),('Authorization','Permit and related approvals','A submitted application is not an issued permit.'),('Delivery','Completed inspections and final acceptance','A payment is not construction approval.')],
 ['Direct: parcel → permitting authority, based on jurisdiction.','Second order, analytical: permit continuity can affect lenders, contractors and utilities.','Third order, conditional: delay or incomplete records can affect housing delivery and future maintenance.'],
 'A changed department name does not itself establish lost records or poorer service. Existing and new projects can have different transition arrangements.',
 ['Confirm jurisdiction before preparing a paid application.','Request a transfer/history checklist for an existing project.'],
 ['Use the official jurisdiction check before choosing a portal.','Retain the old permit number and written transfer instructions.','Ask the responsible agency for the applicable code and fee schedule for the specific project.'],
 [source('county-permits','Pueblo County Building Division','https://pueblopermits.com/','Current portal checked 2026-11-09','City vs County Permits; historical records; transition notice'),source('socobd','Southern Colorado Building Department','https://socobd.com/','Current portal checked 2026-11-09','Transition Notes; 2026 fee/code notices')],
 q('A location-first workflow is the clearest supported action. The transition creates a need to preserve record continuity; it does not establish a service failure.', ['Q inference: project geography, record custody and inspection responsibility should be resolved together. Routing only by a mailing address can produce the wrong workflow.','Q inference: a written handoff reduces uncertainty about which inspections and prior approvals are recognized; it cannot waive applicable safety requirements.'], 'Pre-2026 permits remain part of project history.','Current official pages publish distinct jurisdictions.','Conditional: a repeatable transfer checklist can reduce rework; savings have not been measured.',[option('Confirm routing before applying','Adds an early check but can avoid rework.','Applicant and responsible building authority','Parcel confirmation and the receiving portal in writing.'),option('Preserve the permit chain','Requires matching old and new identifiers.','Records custodians and applicant','Complete permit and inspection sequence, with open conditions.')],['Parcel jurisdiction determination','Any transfer policy and project-specific inspection record'],['Historic approvals can affect present building conditions.','Housing safety and accessibility remain material for children and families.','Keep inspection and maintenance records available for later occupants.'],'Conditional stress: a portal outage or disputed transfer. Preserve local copies and obtain written agency instructions.'),
 ['building permit','permits','pueblo west','boone','socobd','building department'],['Where do I get a building permit in Pueblo West?','Which building department serves the City of Pueblo?'],['REG-074'],
 'Avoid duplicate applications and repeated plan preparation by confirming jurisdiction first. No time or dollar saving is claimed without measurements.')

add('wastewater-2026','Arkansas River sewage discharge: repair, water testing and accountability are different questions','Health & safety',
 'The City’s September 14, 2026 statement describes an August discharge, its account of detection and bypass repair, and a separate water-testing role for CDPHE. That statement does not establish present-day river safety or an independent cause finding.',
 [('Incident account','August 2026 discharge','City-attributed event description','city-spill'),('Public explanation','September 14, 2026','City statement date','city-spill'),('Current river safety','Not established here','Requires current official testing/advisories','city-spill')],
 ['The City attributes the release to a bypass operation and a pipe configuration described in its statement.','The City identifies CDPHE testing and points readers to the state public-health record.'],
 ['Independent engineering cause, regulatory disposition and final repair acceptance have not been reconciled.','A current sampling series, affected uses, notification chronology and costs are not established in this report.'],
 'City Wastewater for its infrastructure account; CDPHE and other competent agencies for testing, regulatory records and current advisories.','Discharge explanation, evidence separation and follow-up accountability.','August incident; September 14 City explanation; source checked November 9.','Arkansas River and potentially affected downstream jurisdictions; exact exposure depends on official data.','Stopping a release, restoring a system and establishing safe downstream use require different evidence.','Compare operating logs, engineering investigation, regulator notices, laboratory results and notification records.',
 [('Authorized repair','Relevant project authority and emergency work orders','Not reconciled.'),('Payment','Invoices and actual outflows','No repair-cost total established.'),('Outcome','System performance and current water-use evidence','No safety conclusion inferred from a completed repair.')],
 ['Direct: wastewater bypass and receiving river, as described by the City.','Second order, conditional: downstream water users, recreation and agriculture may require distinct guidance.','Third order, conditional: service reliability and trust depend on independently reviewable repair and notice records.'],
 'The City is the operator explaining its own incident. Its account deserves attribution, while an independent engineering or regulatory finding may add or change the explanation.',
 ['Publish a source-linked incident chronology.','Compare the repair closeout and sampling record before making a present-safety claim.'],
 ['Use current official advisories for water-use decisions.','Request the incident log, regulator correspondence, laboratory results and repair closeout by date.','Keep estimated discharge, observed flow difference and independently measured impact separate.'],
 [source('city-spill','City of Pueblo — Wastewater discharge follow-up','https://www.pueblo.us/m/newsflash/home/detail/5002','Published 2026-09-14','Detection, bypass explanation and CDPHE reference')],
 q('The strongest supported conclusion is that several accountability questions remain separate. An operator’s explanation cannot substitute for independent cause, exposure or current-safety evidence.', ['Q inference: use a single chronology with separate clocks for discovery, control, agency notification, public notice and test results. This reveals actual timing without presuming delay or fault.','Q inference: an engineering acceptance record and a water-quality result answer different questions. Treating either as a universal closeout can conceal a remaining evidence gap.'], 'Preserve the incident and maintenance history without assuming that old conditions persist.','The cited explanation is historical; no live safety data are available in this report.','Conditional: independently checked repair and notification changes can reduce repeat risk; effectiveness needs later measurement.',[option('Independent incident reconciliation','Requires operating and regulatory records; avoids judging from one statement.','Operator and competent regulator','A dated cause, repair, notification and sampling crosswalk.'),option('Publish a readable closeout','Needs redaction of sensitive infrastructure details.','Responsible agencies','What was repaired, which tests apply, unresolved conditions and next review.')],['Regulator incident and enforcement record','Laboratory sampling dates, locations and applicable standards','Engineering cause and repair acceptance'],['Historical infrastructure choices can affect present reliability.','Any child or family exposure claim needs appropriate public-health evidence; none is inferred here.','Evaluate maintenance, notification and safe access over time at aggregate level.'],'Conditional stress: another bypass or sampling conflict. Use current regulator instructions and preserve contradictory results.'),
 ['wastewater','sewage','sewer spill','arkansas river discharge'],['Does the 2026 sewage-discharge report prove the river is safe today?'],['REG-021'],
 'Use one verified incident chronology across agencies. Reduce repeated information requests while preserving distinct engineering and health evidence.')

add('housing-pipeline','Pueblo housing: permitted, financed, built and occupied are different outcomes','Housing & land',
 'The City’s October 20, 2026 release reports 320 units permitted in 2025 and describes Compass Pointe, Riverly and other housing projects at different development stages. These figures do not establish that all the homes are completed, occupied or affordable to every household.',
 [('2025 units','320','City-reported permitted units','city-housing'),('Compass Pointe','192 homes','City-described development; completion scheduled for 2027','city-housing'),('Riverly','98 proposed units','City-described proposal','city-housing')],
 ['The City release distinguishes a permit count from projects scheduled or proposed for later delivery.','It describes Proposition 123 eligibility and financing arrangements, which need their own award and agreement records.'],
 ['Independent permit-to-completion reconciliation, occupancy, rents and household access have not been verified here.','Project subsidy totals may contain different instruments and overlapping funding sources.'],
 'City Housing and Citizen Services; relevant permitting authority; developers, funding agencies and property operators under their own agreements.','Housing supply stages, public investment and practical affordability.','City release October 20, 2026; 2025 permit statistic; some future project milestones.','City permit totals and individual Pueblo projects; countywide needs are a separate denominator.','A headline production number can coexist with unmet need if units are unfinished, inaccessible, differently priced or in a different geography.','Trace project IDs from permit through financing, construction, acceptance, covenant, occupancy and observed rents.',
 [('Eligibility','Ability to compete for funding','Not an award to every local project.'),('Financing','Bonds, loans, grants, waivers and private equity','Different instruments must not be added as equivalent cash grants.'),('Delivery','Completed and occupied units','Needs completion and occupancy evidence.'),('Outcome','Stable and affordable housing access','Requires income, rent, eligibility and service measures.')],
 ['Direct: project sponsor, funding instruments and permitting body.','Second order, analytical: utilities, contractors, nearby services and transport affect delivery and access.','Third order, conditional: household stability and school continuity depend on actual availability, cost and location.'],
 'Permit growth is a useful supply signal, but it is neither proof that an affordability problem is solved nor evidence that investment has failed.',
 ['Publish a project-by-project pipeline with a single unit identifier.','Compare promised affordability terms with observed rents and access once homes open.'],
 ['Check whether a cited number refers to permits, proposed units, construction, completion or occupancy.','For a named development, request the funding instrument, affordability covenant and latest delivery milestone.','Use the City resource guide for assistance routes; do not infer present vacancies or eligibility from this report.'],
 [source('city-housing','City of Pueblo — Housing production and development statement','https://www.pueblo.us/m/newsflash/Home/Detail/5024','Published 2026-10-20','Permit totals; Compass Pointe; Riverly; Proposition 123'),source('housing-help','City of Pueblo — Housing and Homelessness Guide','https://www.pueblo.us/2949/Housing-and-Homelessness-Guide','Guide checked 2026-11-09','Service categories; provider details require current confirmation')],
 q('The useful measure is conversion through the housing pipeline, together with who can actually obtain a home. Aggregate permit growth cannot answer those distribution and delivery questions.', ['Q inference: a unit-level pipeline prevents proposed and completed homes from being counted together. It also makes delays visible without assuming their cause.','Q inference: public financing is best evaluated against enforceable affordability, delivery and access conditions. A financing announcement alone is too early to claim a household outcome.'], 'Keep prior permit definitions, city boundaries and project amendments when comparing years.','The source establishes the City’s dated account of the pipeline.','Conditional: completed homes could improve access, but rents, eligibility, transport and household resources determine the experienced benefit.',[option('Track conversion and delays','Requires matching identifiers across agencies.','Housing staff, permit authority and project operator','Permit → financed → completed → occupied counts without duplicates.'),option('Measure affordability after opening','Requires privacy-preserving aggregate data.','Funding agency and operator','Covenant terms, actual rents, eligible demand and access barriers.')],['Completion and occupancy records','Executed affordability covenant and financing agreements','Comparable rent, income and access measures'],['Past shortages and land choices need dated evidence, not assumed causes.','Housing stability can matter for school and care continuity; project-level effects are not measured here.','Compare long-lived affordability terms and infrastructure obligations with later household outcomes.'],'Conditional stress: financing delay, construction overrun or higher operating costs. Compare continuity and affordability protections under each scenario.'),
 ['housing','riverly','compass pointe','affordable homes','proposition 123'],['Do Pueblo housing permit totals equal completed homes?','What stage is Riverly described as in the October 2026 City statement?'],['REG-046','REG-068'],
 'Reuse one project pipeline instead of repeatedly reconciling press-release totals. Include infrastructure, operating costs and staff review where documented.')

add('aspen-recovery','Aspen Acres recovery: a disaster declaration is not the same as individual assistance','Environment & place',
 'Pueblo County’s rebuilding page, updated October 19, 2026, describes a major-disaster declaration supporting infrastructure and debris work while distinguishing denied individual-assistance portions. Its damage-registration portal is explicitly not a FEMA individual-assistance application. Later amendments and appeal outcomes still need checking.',
 [('County guidance date','October 19, 2026','Published page update','county-recovery'),('Damage registration','Not an individual-assistance application','Explicit County distinction','county-recovery'),('Federal declaration record','FEMA-4944-DR','Amendment identifies declaration dated September 1, 2026','federal-amendment')],
 ['The County page separates damage reporting, rebuilding permits and assistance pathways.','A Federal Register amendment identifies FEMA-4944-DR; its general funding-code list is not proof that every assistance program is authorized for every survivor.'],
 ['Latest appeal or assistance amendments, applicant eligibility and remaining program deadlines are not independently reconciled.','Amounts committed, paid by insurance, paid by public programs and provided by charities may overlap.'],
 'FEMA and state authorities for authorized federal programs; County agencies for local rebuilding processes; each aid provider for its own eligibility and application.','Recovery pathways, assistance categories and evidence needed to measure progress.','County page updated October 19; federal amendment published November 3; checked November 9.','Fire-affected Pueblo/Custer region as applicable to each specific program.','A household could otherwise register damage and reasonably, but incorrectly, believe a separate aid application is complete.','Confirm current program authorization, eligible geography, applicant requirements, application receipt and funding stage with the responsible provider.',
 [('Authorized program','Declaration and program-specific designation','Not every assistance category follows automatically.'),('Application or registration','Different administrative purposes','A damage report is not proof of an aid application.'),('Award and payment','Provider-specific decision and disbursement','No household award is determined here.'),('Recovery','Safe housing, utilities and durable restoration','Not established by dollars announced or a permit alone.')],
 ['Direct: applicant or public project → specific assistance authority.','Second order, analytical: insurance, debris work, utilities, permits and rebuilding can constrain each other.','Third order, conditional: school, employment and household stability depend on durable recovery rather than one milestone.'],
 'A declaration can be real while a particular assistance category is unavailable or contested. An old request, a general program-code list and a current individual award are not interchangeable.',
 ['Publish a dated program-status table.','Track aggregate recovery stages with separate funding categories and no personal survivor profiles.'],
 ['Open the latest County guidance and the relevant program’s current official instructions before acting.','Confirm separate application requirements and retain receipts.','Do not treat older listed deadlines or service hours as current without provider confirmation.'],
 [source('county-recovery','Pueblo County — Aspen Acres rebuilding resources','https://pueblopermits.com/aspen-acres-fire-recovery-resources/','Page updated 2026-10-19','FEMA information; damage registration; program deadlines'),source('federal-amendment','Federal Register — Declaration amendments, FEMA-4944-DR section','https://public-inspection.federalregister.gov/2026-22371.pdf','Published 2026-11-03','PDF page 16, Colorado amendment; not individual eligibility', 'A0')],
 q('Recovery information must be organized by program and applicant, not by the existence of one declaration. The present evidence supports clear distinctions but not an eligibility decision or a claim that recovery is complete.', ['Q inference: a pathway should make registration, application, award, payment, physical repair and durable recovery visible as separate steps.','Q inference: combine aid data only after checking overlap with insurance and other providers; otherwise an aggregate total can overstate resources actually available for unmet needs.'], 'Preserve requests, original decisions and amendments; an earlier incomplete search is not controlling authority.','Use the dated County and federal records within their scopes. Current amendments and deadlines remain a recheck requirement.','Conditional: track housing, utility and service restoration to assess whether recovery is durable.',[option('Program-status and deadline register','Requires frequent official checks; prevents expired offers appearing current.','Program administrators and local information custodians','Authorization, eligibility, deadline, application route and checked date.'),option('Aggregate recovery pathway','Needs privacy controls and common definitions.','Authorized recovery partners','Stage counts, blockers and independently documented completion.')],['Latest FEMA/state program designation or appeal decision','Current provider deadlines and application confirmation','Separated public, insurance and charitable disbursement totals'],['Disaster losses and assistance requests require their original dates.','Protect survivor identities; measure school, housing and care continuity only in appropriate aggregates.','Evaluate rebuilding resilience, affordability and recurring maintenance without claiming a model predicts future loss.'],'Conditional stress: another disruption or provider outage. Keep dated official alternatives and a human assistance route; this report is not an emergency-status feed.'),
 ['aspen acres','fire recovery','fema','disaster assistance'],['Is Aspen Acres damage registration a FEMA individual-assistance application?'],['REG-025'],
 'Use one current program register and reusable document checklist. Avoid duplicate applications and measure review burden; no saving or aid amount is inferred.')

add('lime-road-costs','Lime Road and St Charles: what a commitment line can—and cannot—tell us','Roads & transport',
 'The April 2026 Half-Cent report lists $7,990,246 for St Charles public improvements under project ED2503. That dated commitment is not a verified total for all Lime Road work, a payment total, or a cost attributable solely to Project Falcon.',
 [('ED2503 line','St Charles public improvements','Named project in fund report','ed-april'),('Listed amount','$7,990,246','Dated commitment, not a verified road payment','ed-april'),('Whole Lime Road cost','Not established','Scope, contracts and transactions required','ed-april')],
 ['The report identifies a specific project code and amount within a larger commitments table.','The report’s May 13 data date limits reuse as a present balance or latest project estimate.'],
 ['Exact road limits, city/county asset ownership, utility scope and separate project agreements are not reconciled here.','A complete authorization-to-payment ledger and cost-sharing allocation are still needed.'],
 'Relevant City and County authorities, fund custodians, asset owners and contracted delivery parties, to be resolved by road segment and agreement.','Infrastructure cost boundaries, funding stages and allocation of shared benefits.','April report, data as of May 13, 2026; explanation prepared November 9.','St Charles industrial area and any separately evidenced Lime Road segments.','A shared road or utility corridor can serve several users; one commitment line cannot fairly assign all public costs to one company.', 'Define the physical scope, identify each owner and agreement, reconcile project codes, eliminate overlapping costs, and match payments to accepted work.',
 [('Commitment','$7,990,246 listed for ED2503','Dated fund report only.'),('Contract','Executed scope and amendments','Not reconciled here.'),('Paid','Invoices and transaction entries','Not established by the commitment.'),('Allocation','Shares by agreement or defensible benefit method','No company-specific share calculated.'),('Lifecycle','Maintenance, replacement and operating obligations','Not included in a verified total.')],
 ['Direct: ED2503 commitment → its described public-improvements scope.','Second order, conditional: adjacent land users and utilities may benefit under different agreements.','Third order, conditional: freight access, fiscal obligations and regional development depend on what is actually delivered and maintained.'],
 'Infrastructure can have value beyond one prospect, but that does not establish a particular allocation as fair. Both exclusive-beneficiary and universal-benefit claims need evidence.',
 ['Build one segment-and-project-code cost ledger.','Compare allocation methods without implying each produces an additional cost.'],
 ['Request ED2503 authorization, scope, amendments, invoices and payment detail.','Request executed cost-sharing and maintenance agreements for each road segment.','Compare no-build, safety-only and broader-capacity alternatives using the same lifecycle boundary.'],
 [source('ed-april','City of Pueblo — April 2026 Economic Development Cash Recap','https://www.pueblo.us/ArchiveCenter/ViewFile/Item/5528','Data as of 2026-05-13','PDF page 2, ED2503 commitment row','A0')],
 q('The available record supports one commitment line, not a consolidated road-cost or company-benefit conclusion. Q’s useful contribution is a defensible cost boundary and an allocation test that can be disproved by better records.', ['Q inference: combine road, drainage, utility and maintenance costs only after defining which physical assets and beneficiaries belong in the comparison.','Q inference: show alternative allocations side by side—contractual responsibility, incremental demand and shared public use—without adding the alternatives together.','A canceled or delayed private project does not automatically make every infrastructure cost worthless; equally, potential shared use is not proof of an adequate public return.'], 'Preserve original commitments, option/land instruments and earlier scope estimates.','One historical project line is verified; current total exposure remains unknown.','Conditional: phased delivery can preserve options, but may change unit cost and utility coordination.',[option('Safety-only or phased scope','Can limit early exposure but may raise later mobilization or coordination costs.','Lawful asset owner and approving body','Documented safety requirement, phase boundaries and full lifecycle comparison.'),option('Full corridor investment','May serve more users but needs demand and cost-sharing evidence.','Approving bodies and benefiting asset owners','Comparable alternatives, executed contributions and measurable use.')],['Segment-level asset ownership and design scope','Executed funding and maintenance agreements','Project-code transaction and acceptance records'],['Earlier land and infrastructure choices may create continuing obligations.','Assess public-service opportunity costs and safe access without inferring effects on individual families.','Include maintenance and replacement burdens borne by future residents.'],'Conditional stress: prospect withdrawal, construction escalation or uncollected partner contribution. Compare recoverable funds, sunk cost and continuing public use.'),
 ['lime road','st charles','project falcon','ed2503','industrial infrastructure'],['Does the $7,990,246 St Charles commitment prove the total spent on Lime Road?'],['REG-007','REG-008','REG-039','REG-043'],
 'Reconcile the largest overlapping project codes first. Compare physical resources, road maintenance and staff effort as well as dollars; no unsupported EE score is assigned.')

add('water-budget-evidence','Pueblo Water: a budget, an audit and a household bill answer different questions','Water & energy',
 'Pueblo Water’s finance page lists a 2026 budget and a 2025 annual financial report. The latter includes an independent audit opinion on specified 2025/2024 financial statements. Neither document alone determines a household’s current bill, affordability, future rate or system reliability.',
 [('Planning document','2026 budget listed','Finance-page listing, not a reproduced budget audit','water-finance'),('Historical statements','2025 and 2024','Periods covered by cited audit opinion','water-acfr'),('Current household cost','Not calculated','Needs applicable tariff and actual usage','water-finance')],
 ['The finance hub provides annual budgets and annual financial reports as different document series.','The auditors’ report states its financial-statement scope; it is not a guarantee of every operating or policy outcome.'],
 ['Budget tables, tariff schedules and a representative bill model have not been fully reconciled here.','Current service performance, household affordability and future rate decisions require additional evidence.'],
 'Pueblo Water’s Board and authorized management for their respective decisions; auditors for the stated financial-statement opinion; other service providers retain their own jurisdictions.','How to connect financial planning, audited results and experienced water cost.','2026 budget listing; 2025/2024 audited statement periods; checked November 9.','Pueblo Water service and financial scope, not all water systems in Pueblo County.','Water-rate debate can be distorted by treating budgeted capital, depreciation, cash and household bills as the same measure.','Read budget, actual statements, cash-flow notes, debt and capital schedules alongside the applicable tariff and service data.',
 [('Budget','Planned revenue, capital and operating activity','Not proof of actual cash movement.'),('Audited statements','Historical financial reporting under the stated opinion','Not a forecast or universal internal-control assurance.'),('Bill','Applicable fixed and usage charges','Requires the specific tariff, customer class and consumption.'),('Outcome','Reliable and affordable service','Needs operating and household-impact measures.')],
 ['Direct: Board financial decisions, utility operations and customers.','Second order, analytical: energy, treatment, construction and debt costs can affect operating needs.','Third order, conditional: maintenance choices and affordability influence long-term service access.'],
 'An audit opinion is meaningful within its scope. It neither establishes that all rates are optimal nor supports dismissing audited accounts as irrelevant.',
 ['Publish a budget-to-actual capital and operating crosswalk.','Model representative bills only with a verified tariff and explicit usage assumptions.'],
 ['Open both the budget and annual financial statements, preserving their reporting periods.','For a bill question, identify the provider, customer class and tariff before comparing costs.','Request measured service and capital-delivery results before inferring reliability from spending.'],
 [source('water-finance','Pueblo Water — Financials','https://pueblowater.org/our-board/financials/','Finance listing checked 2026-11-09','Budgets and Annual Comprehensive Financial Reports'),source('water-acfr','Pueblo Water — 2025 Annual Comprehensive Financial Report','https://pueblowater.org/wp-content/uploads/2026/03/2025-ACFR-2025-Linked.pdf','FY2025/2024 financial statement periods','PDF page 23, Independent Auditors’ Report; selected scope only','A0')],
 q('A useful water-cost answer needs three linked views: planned resources, historical financial results and the actual service/bill experienced by customers. No single view can replace the other two.', ['Q inference: a capital program may increase current financing needs while reducing later failure risk; evaluating it requires asset condition, delivery and maintenance evidence.','Q inference: average revenue per customer is not a household affordability measure. Customer class, usage, fixed charges and household resources change the comparison.'], 'Use compatible fiscal periods and retain prior capital and debt commitments.','The report establishes document availability and the stated audit scope; it does not reproduce the full financial analysis.','Conditional: compare maintenance, energy costs, drought or construction changes with documented sensitivity inputs.',[option('Reconcile capital delivery with accounts','Requires project milestones and accounting treatment.','Utility management and Board','Authorized cost, contract, payment, acceptance and service improvement.'),option('Show representative bill scenarios','Useful only with verified tariffs and clearly stated usage.','Tariff authority and public reviewers','Reproducible bill calculations, without inferring individual eligibility or hardship.')],['Current tariff and Board rate decisions','2026 budget and actual financial crosswalk','Asset-condition, service-performance and capital-acceptance records'],['Earlier asset and debt choices can affect present costs.','No individual household hardship is inferred from a bill or neighborhood.','Compare future maintenance and service continuity with long-lived debt and replacement obligations.'],'Conditional stress: energy-cost increase, drought or capital overrun. Quantify only with validated cost, demand and capacity inputs.'),
 ['pueblo water','water budget','water bill','water rates','water financials'],['Does Pueblo Water’s annual audit establish my current water bill?'],['REG-050'],
 'Use the smallest sufficient financial and operational evidence set. Include pumping/treatment energy only where measured; no kWh, dollar or EE score is invented.')

add('records-request','Getting the records that could resolve a disputed public-spending claim','Government & law',
 'A focused request for existing authorizations, agreements and payment records is more useful than asking a custodian to prove a broad allegation. Colorado’s legislative legal summary explains CORA, custodians, exceptions and potential research/retrieval charges; the current custodian policy and applicable law still control.',
 [('Request target','Existing responsive records','Not a demand to create a new analysis','cora-summary'),('Responsible recipient','Custodian of the particular record','May differ by agency or record type','cora-summary'),('Fees and exclusions','May apply','Check current law and custodian policy','cora-summary')],
 ['The legislative legal summary describes broad public-record coverage, custodians and exceptions.','It distinguishes electronic-copy handling from research/retrieval charges; a request should ask for a written estimate before chargeable work.'],
 ['No individual request’s legal status, deadline, exemption or fee is determined here.','The correct custodian, exact record existence and any separate criminal-justice or federal process require confirmation.'],
 'The custodian holding the relevant record; the requester approves scope and any cost; legal disputes require the appropriate formal process.','A usable evidence request and a receipt-based follow-up method.','Legislative summary published October 30, 2025; source checked November 9, 2026.','Colorado state/local public records within applicable law; federal and tribal processes differ.','A specific request can test a public claim without presuming that missing information proves misconduct.','Identify record classes, project identifiers, date range, custodian, electronic format and cost limit; retain the response and any stated withholding basis.',
 [('Requested records','Authorizations, agreements, invoices and payments','Each answers a different stage question.'),('Retrieval cost','Possible custodian charges','Ask for an estimate; no payment authorization is implied.'),('Finding','Analysis after records are obtained','Silence or a partial return is not proof of wrongdoing.')],
 ['Direct: a specific claim → existing record class → custodian.','Second order, analytical: shared projects may require records from more than one government.','Third order, conditional: accessible records can improve correction and public understanding without establishing a favorable outcome.'],
 'A custodian may lawfully withhold or redact material, may not hold the record, or may use another process. Those possibilities must be recorded before inferring concealment.',
 ['Start with the narrowest material transaction or decision.','Expand only when the returned records reveal a specific remaining gap.'],
 ['Use the report’s records-request download as an editable draft, not an automatically sent request.','Confirm the recipient and current policy before sending.','Retain the original request, acknowledgement, estimate, response and any appeal or correction.'],
 [source('cora-summary','Colorado General Assembly OLLS — Colorado Open Records Act legal summary','https://content.leg.colorado.gov/sites/default/files/colorado-open-records-act-cora-colorado-law-summary-accessible.pdf','Summary published 2025-10-30','Pages 1–3: scope, custodian, response, exclusions and fees; general overview, not legal advice','A0')],
 q('The most useful first step is to define the proposition that needs testing and request the existing records capable of testing it. A document return is evidence to analyze, not an automatic verdict.', ['Q inference: split a broad spending allegation into authority, scope, obligation, cash and delivery questions. This reduces ambiguity and avoids adding unlike amounts.','Q inference: record the reason for each gap—no record held, withheld, pending, missing identifier or unavailable format—because those states imply different next steps.'], 'Preserve the original statement and the versions of documents that were available at that time.','Current custodian rules and applicable law must be checked for the particular request.','Conditional: a narrower follow-up can resolve remaining gaps with less agency and requester effort.',[option('Focused first request','May need follow-up but lowers unnecessary retrieval burden.','Requester and record custodian','A bounded date range, project IDs and specific existing record classes.'),option('Cross-agency reconciliation','Adds work; needed when responsibility and cash cross jurisdictions.','Requester, custodians and reviewers','Common identifiers and explicit treatment of overlapping or withheld records.')],['Actual request acknowledgement and response','Current custodian fee and access policy','The specific authorizing, contracting, payment and delivery documents'],['Earlier requests and responses remain part of the audit trail.','Request aggregate program records rather than private child or client files.','Keep retention, correction and access needs visible without assuming permanent availability.'],'Conditional stress: a source disappears or a request is narrowed. Preserve lawful copies and the exact response; do not bypass access controls.'),
 ['cora','public records','records request','documents','request invoices'],['How do I request records to check a public-spending claim?'],['REG-027'],
 'Bound dates and record classes, reuse prior lawful disclosures and approve cost estimates before additional retrieval work.')

add('pueblo-flood-history','The 1921 Pueblo flood: connecting historical evidence to present resilience','Culture & history',
 'CSU Pueblo’s archive identifies a collection of photographs, newspaper material and printed records about the 1921 flood, including material dated 1921, 1956 and 1971. The collection is accessible, but its record warns that not all material is in the public domain. Historical damage evidence does not establish today’s parcel-level flood risk.',
 [('Historical event','June 1921 flood','Event described by the institutional archive','csu-flood'),('Collection dates','1921, 1956, 1971','Different material dates, not one simultaneous account','csu-flood'),('Reuse rights','Item-specific review required','Access does not equal reproduction permission','csu-flood')],
 ['The archive describes newspaper, photograph, postcard and printed material related to the flood.','Its collection description identifies access, rights and acquisition-provenance limits.'],
 ['Individual photographs and claims still need item-level identification, dates and context.','This report does not determine a present flood zone, engineering capacity or the exact historical death toll.'],
 'CSU Pueblo University Archives and Special Collections for the collection; relevant present-day authorities for modern flood and infrastructure determinations.','Historical source interpretation, rights and a bounded connection to resilience.','Flood in 1921; later collection material and retrospective interpretations must retain their own dates.','Pueblo historical places; current locations and hazard boundaries need independent verification.','A historical image can explain a city’s development while still being insufficient evidence for a current hazard claim.','Identify the original item, creator/date/context, source chain and rights; compare any present-day claim with current maps and engineering records.',
 [('Historical estimate','Damage figures in historical sources','Not converted to present dollars or treated as an audited total here.'),('Modern investment','Current mitigation and maintenance','Requires its own authority, design and budget records.'),('Outcome','Present resilience','Cannot be inferred from an archival photograph.')],
 ['Direct: source item → documented historical place or event.','Second order, analytical: rebuilding and infrastructure decisions can be investigated through later records.','Third order, conditional: present resilience lessons require current hydrology, land-use and maintenance evidence.'],
 'A retrospective account can differ from contemporary reporting without implying deception. Collection gaps and uncertain acquisition history should remain visible.',
 ['Publish attributed item-level historical exhibits.','Link historical questions to a separately sourced modern resilience analysis.'],
 ['Use the archive’s preferred citation and check each item’s reuse rights.','Distinguish the event date, document date and later interpretation.','For current risk, obtain present official hazard and infrastructure records rather than extrapolating from historical scenes.'],
 [source('csu-flood','CSU Pueblo Library — 1921 Pueblo Flood materials collection','https://csupueblo.libraryhost.com/index.php?id=4&p=collections/controlcard&q=Pueblo+flood','Collection dates 1921, 1956, 1971; checked 2026-11-09','Scope, historical description, acquisition note and rights','B')],
 q('The archive is valuable both as community memory and as a starting point for questions about rebuilding and resilience. It should preserve multiple dated sources while keeping modern hazard conclusions separate.', ['Q inference: a history page is stronger when a reader can trace a narrative to a specific item and see what is original, retrospective or uncertain.','Q inference: resilience learning requires an explicit bridge from the historic event to present conditions. Without that bridge, a dramatic image can exaggerate or understate current risk.'], 'Keep the 1921 event distinct from later collection and interpretation dates.','The collection supplies a historical research pathway, with rights and provenance limits.','Conditional: historical lessons can inform questions for modern planning, but do not replace engineering evidence.',[option('Curated source-linked exhibit','Requires item-level rights and context review.','Archive custodian and editors','Item identifiers, dates, attribution, uncertainty and permitted reuse.'),option('Historical-to-current comparison','Requires compatible geographic and engineering evidence.','Researchers and competent planning authorities','Clear separation of historical observation from current hazard assessment.')],['Item-level catalogue and reproduction permission','Contemporary corroborating records','Modern flood and infrastructure evidence for any current claim'],['Document lived history without erasing uncertainty or overlooked communities.','Use age-appropriate historical learning and avoid identifying vulnerable residents.','Preserve accessible memory and distinguish lessons from untested predictions.'],'Conditional stress: archival loss or misleading reuse. Preserve provenance and rights-reviewed copies; avoid publishing unsafe access locations.'),
 ['1921 flood','pueblo history','historical flood','archives','heritage'],['Can a 1921 flood photograph establish my property’s flood risk today?'],['REG-026','REG-056'],
 'Reuse verified item metadata and lawful archival copies. Reserve deeper reconstruction for material questions; no disaster-loss or risk model is implied.')

add('pueblo-boulevard-agenda','Pueblo Boulevard: reconciling the funding listed on the October 26 agenda','Roads & transport',
 'The October 26, 2026 Council agenda lists proposed funding sources totaling $2,058,277.00 for road and signal work, matching its listed $1,658,277.00 construction contract plus $400,000.00 contingency. This is an arithmetic reconciliation of agenda amounts, not evidence of adoption, execution, payment or final cost. The adjacent PURA reimbursement item needs its own agreement.',
 [('Half-Cent transfer','$1,756,383.40','Listed ED2606 funding proposal','council-oct26'),('Acero signal deposit','$32,561.60','Listed transfer from D1801 into CI2623','council-oct26'),('Laredo signal deposit','$19,332.00','Listed transfer from D0201 into CI2623','council-oct26'),('Martinez contribution','$250,000.00','Listed acceptance/appropriation into CI2623','council-oct26'),('Listed sources total','$2,058,277.00','Calculated from the four agenda amounts; not cash paid','council-oct26')],
 ['Agenda N12 names ED2606, CI2623, C&D Electric, Inc. and a $1,658,277.00 construction contract with $400,000.00 contingency.', 'Arithmetic: 1,756,383.40 + 32,561.60 + 19,332.00 + 250,000.00 = 2,058,277.00; 1,658,277.00 + 400,000.00 = 2,058,277.00.', 'Agenda N13 separately lists a City–PURA reimbursement agreement for traffic improvements between Acero Avenue and Mirror Avenue. The agenda excerpt does not reproduce the agreement terms.'],
 ['Final adopted ordinance, amendments, roll-call vote, executed contract, reimbursement terms and actual payments are not established here.', 'Whether contingency was used, the final allocation between accounts, maintenance responsibility and accepted construction outcomes require later records.'],
 'City Council for the listed ordinance process; City Purchasing for the listed contract execution role; City Finance for account reconciliation; PURA for its separate agreement and Board authority.',
 'An agenda-level funding and contract reconciliation, with separate transaction states.', 'October 26, 2026 agenda, PDF page 3, N12–N13; retrieved November 10. The listed motion sets November 9 hearings; it is not a recorded final vote.',
 'State Highway 45A / Pueblo Boulevard; N13 describes Acero to Mirror. Exact construction limits remain governed by the plans and executed instruments.',
 'Four sources can be compared with contract and contingency only when their scopes match. Reimbursement obligations must not be added again as if all were new public cost.',
 'Match project IDs, authorizations, executed instruments, invoices, payments and acceptance records; reconcile fund transfers without double counting.',
 [('Listed sources','Four agenda amounts sum to $2,058,277.00','Arithmetic of proposals, not cash received.'),('Listed contract','$1,658,277.00','Agenda item; execution and payments not established.'),('Contingency','$400,000.00','Allowance, not an incurred expense.'),('Reimbursement','Separate City–PURA instrument in N13','Amount, eligibility and repayment terms not established by this agenda.')],
 ['Source-named: City project accounts, C&D Electric and Martinez Property Holdings, Inc. in N12.', 'Source-named: City and PURA in N13; adjacent listing does not establish identical costs or reimbursement terms.', 'Second-order questions: utility interfaces, adjacent access and maintenance responsibilities need plans and agreements.', 'Third-order questions: mobility, emergency access, local commerce and future upkeep need measured outcomes; no causal benefit is asserted.'],
 'A balanced list of proposed sources and uses does not establish that a project is fully funded in cash, that costs are final, or that the PURA agreement covers the entire amount. Later amendments could change this baseline.',
 ['Reconcile adopted and executed versions to the agenda baseline.','Publish eligible reimbursement, invoices and payments by shared project IDs without adding the same cost twice.'],
 ['Read PDF page 3 and distinguish N12 from N13.','Obtain the final ordinance, executed construction and reimbursement agreements, amendments, invoices and acceptance record.','Compare actual payments with authorized scope and document any unused or spent contingency.'],
 [source('council-oct26','City of Pueblo — October 26, 2026 Council agenda','https://pueblo.granicus.com/DocumentViewer.php?file=pueblo_4d7361378191251092f2c6b1ac3fbd40.pdf&view=1','Agenda dated 2026-10-26','PDF page 3, N12, N13 and proposed consent motion','A0')],
 q('The agenda supports a precise planning reconciliation while leaving the legal and delivery states open.', ['Q arithmetic: listed sources equal listed construction plus contingency; equality does not prove collection or spending.', 'Q inference: a reimbursement flow may repay an already-counted eligible cost. The signed agreement and ledger determine whether it is a source, obligation or payment.'],
 'Preserve the October 26 proposal and later amendments as separate editions.', 'The original agenda has been retrieved; final adoption and delivery records remain open.', 'Conditional: scope changes, unused contingency or reimbursement conditions can alter final public exposure.',
 [option('Single project-code reconciliation','Requires both governments and separate account states.','City Finance, project owner and PURA','Adopted amount, executed terms, invoices, payments and final acceptance.'),option('Verify milestones before benefit claims','Adds engineering and service review.','Responsible public-works and oversight roles','Accepted work, maintenance allocation, operating performance and corrections.')],
 ['Final ordinance and recorded vote','Executed N12 contract and N13 reimbursement agreement','Payment, contingency and construction acceptance records'],
 ['Historic road and funding choices affect present access.','Assess school routes and accessible crossings using plans and measured conditions; no child exposure is inferred.', 'Keep upkeep obligations and safe access visible over the asset lifecycle.'],
 'Conditional stress: overruns or delayed reimbursement. Separate authorized contingencies, cash timing, eligible costs and reversible scope changes.'),
 ['pueblo boulevard','acero','mirror avenue','ed2606','ci2623','co45'],['Do the Pueblo Boulevard agenda funding amounts reconcile?'],[],
 'Reuse one project-ID ledger across authorizations, construction and reimbursement. No measured savings or resource score is claimed.')
