issue_ids={
 'budget-2026': [], 'half-cent-2026': ['REG-001','REG-004'],
 'csac-2027': ['REG-049'], 'permits-jurisdiction': ['REG-074'],
 'wastewater-2026': ['REG-050'], 'housing-pipeline': ['REG-046','REG-068'],
 'aspen-recovery': ['REG-025'], 'lime-road-costs': ['REG-007','REG-008'],
 'water-budget-evidence': [], 'records-request': ['REG-036'],
 'pueblo-flood-history': [], 'county-priorities-2026': [], 'city-mill-levy-2026': [], 'pueblo-boulevard-agenda': []}
for r in reports:
    # Packet-family groupings include adjacent topics, not direct assertions.
    r['issueIds']=issue_ids[r['slug']]
    r.setdefault('version','2.0.0')
    r['sourceChecked']='2026-11-10' if r['slug']=='pueblo-boulevard-agenda' else DATE
    r['reviewDue']='2026-11-16' if r['slug'] in ['budget-2026','csac-2027','aspen-recovery'] else '2026-12-09'
    r['publicationClass']='PUBLIC_EXPLANATORY_ANALYSIS'
    r['independentAudit']=False
    for f in r['keyFacts']:
        if 'source' not in f and len(r['sources'])==1:
            f['source']=r['sources'][0]['id']
    r['claims']=[dict(id=f"{r['id']}-C{i+1:02}",claim=f['label']+': '+f['value'],classification='SOURCE_ATTRIBUTED',sourceIds=[f['source']],boundary=f['stage']) for i,f in enumerate(r['keyFacts'])]
    r['recordsNeeded']=r['qification']['reopen']
    for source_record in r['sources']:
        source_record.setdefault('checked',DATE)
        source_record.setdefault('role','A0' if 'ordinance' in source_record['id'] or 'april' in source_record['id'] else 'A2')
        source_record.setdefault('locator','See the named document and stated reporting period; no wider source claim implied.')
        source_record.setdefault('scope','Supports the attributed proposition only; no independent outcome audit implied.')
